/* 告警示例: 查对象 → legacy 高亮；生命周期由宿主逐对象释放 */
const color = '#ff1744';
const list = ssp.objectsTool.getByUserDataProperty('renderType', 'CEILING');
list.forEach(o => ssp.objectsTool.setHighlight(o, color, true));
console.log(`alarm triggered: ${list.length} ceilings flashing in ${color}`);

/* 结束时只释放本次对象；模板内不得创建 timer 或执行全局清理 */
list.forEach(o => ssp.objectsTool.unHighlight(o));
